#include "fractal/workspace_controller.h"
#include <assert.h>
int main(void){fractal_workspace_controller c;uint64_t first;assert(fractal_workspace_controller_init(&c,FRACTAL_ANALYSIS_DEFERRED)==0);assert(fractal_workspace_controller_apply_configuration(&c,&c.configuration)==0);assert(fractal_workspace_controller_start(&c)==0);assert(fractal_workspace_controller_wait(&c,8)==0);first=c.progress.generation;assert(c.analysis.state==FRACTAL_ANALYSIS_COMPLETED);assert(fractal_workspace_controller_rapid_edit(&c,3)==0);assert(c.progress.generation>first);assert(c.cost.jobs_requested>0);assert(fractal_workspace_controller_wait(&c,8)==0);assert(c.analysis.generation==c.progress.generation);assert(c.analysis.state==FRACTAL_ANALYSIS_COMPLETED);assert(c.service.workspace.analysis_reference==c.analysis.result_identity);return 0;}
